# -*- coding: utf-8 -*-
# 🏁 Coding Test Besar: muncul setiap 5 bab. Satu kasus, 3 bagian yang saling menyambung (A → B → C).
# Bagian berikutnya terbuka setelah bagian sebelumnya lulus. Dibaca terakhir oleh alat/buat-lab-python.py.

PANDUAN = dict(judul="Cara mengerjakan coding test besar",
  penjelasan="<p>Coding test besar terdiri dari <b>3 bagian</b> dalam satu cerita. Bagian B memakai hasil bagian A, dan bagian C memakai A dan B, sama seperti tugas kerja sungguhan. Kode bagian sebelumnya otomatis ikut di editor, jadi kamu tinggal menambahkan fungsi baru di bawahnya.</p><ol><li>Baca ketiga bagian dulu supaya tahu arah akhirnya.</li><li>Kerjakan bagian A sampai lulus, lalu lanjut.</li><li>Pecah masalah menjadi fungsi kecil, uji dengan ▶ Jalankan dan <code>print()</code>.</li><li>Sisakan waktu untuk kasus tepi: data kosong, nol, nilai sama.</li></ol><p class=\"kecil\">Target waktu: ±45–60 menit untuk ketiga bagian.</p>",
  kode='# Pola kerja: fungsi kecil yang saling memanggil\ndef bersihkan(teks):\n    return teks.strip().lower()\n\ndef hitung(daftar):\n    return {k: daftar.count(k) for k in set(daftar)}\n\ndef laporan(teks_mentah):\n    data = [bersihkan(t) for t in teks_mentah]   # memakai fungsi A\n    hasil = hitung(data)                          # memakai fungsi B\n    return sorted(hasil.items())\n\nprint(laporan([" Kopi", "teh ", "KOPI"]))',
  kunci="Bagian C hampir selalu memakai fungsi bagian A dan B. Jangan menulis ulang, panggil saja.")

def ujian(id, topik, setelah, judul, cakupan, cerita, bagian, pre=""):
    """bagian: list 3 dict (judul, fungsi, soal, solusi, tes, petunjuk, jelas, cek, awal_tambahan).
    Solusi dan kode awal setiap bagian menyertakan solusi bagian sebelumnya."""
    langkah, sebelumnya = [], ""
    for n, b in enumerate(bagian):
        huruf = "ABC"[n]
        solusi = sebelumnya + b["solusi"]
        awal = sebelumnya + b["awal"]
        langkah.append(L(f"{id}-{huruf.lower()}", f"Bagian {huruf}: {b['judul']}", min(3, n + 2), b["fungsi"],
            b["soal"], solusi, b["tes"], b["petunjuk"], b["jelas"], cek=b.get("cek"), awal=awal,
            cerita=cerita if n == 0 else f"Lanjutan dari bagian {'AB'[n - 1]}. Kode bagian sebelumnya sudah ada di editor; tambahkan kodemu di bawahnya.",
            pre=pre, contoh=b.get("contoh", 2)))
        if n:
            langkah[-1]["awal_baru"] = b["awal"]   # browser: kode lulus milik pengguna + bagian baru
        sebelumnya = solusi + "\n\n"
    studi(id=id, topik=topik, setelah=setelah, judul=judul, ujian=True, cakupan=cakupan, contoh=PANDUAN, langkah=langkah)

