ujian("uji-ct-1", "ct", "model", "Impor pelanggan ke Odoo", "Bab 1–5: strategi, membaca kode, algoritma, otomasi data, model & field",
  "Klien mengirim file CSV pelanggan dari sistem lama. Datanya kotor: spasi berlebih, email huruf besar, nomor telepon beragam, dan ada pelanggan kembar. Kamu menyiapkan data sebelum dibuat di model res.partner.",
  [dict(judul="Membaca dan membersihkan CSV", fungsi="baca_pelanggan",
     soal="Buat <code>baca_pelanggan(teks_csv)</code> (header <code>nama,email,telepon</code>). Kembalikan list dict <code>{\"name\", \"email\", \"phone\"}</code>: nama di-<code>strip()</code> lalu <code>title()</code>; email di-strip dan huruf kecil (kosong → None); telepon: buang semua selain angka, awalan 0 diganti 62, beri awalan +, dan None bila hasilnya kosong atau panjang angkanya di luar 10–15. Baris tanpa nama dilewati.",
     solusi='import csv, io, re\n\n\ndef rapikan_hp(teks):\n    angka = re.sub(r"\\D", "", teks or "")\n    if angka.startswith("0"):\n        angka = "62" + angka[1:]\n    return "+" + angka if 10 <= len(angka) <= 15 else None\n\n\ndef baca_pelanggan(teks_csv):\n    hasil = []\n    for b in csv.DictReader(io.StringIO(teks_csv)):\n        nama = (b.get("nama") or "").strip()\n        if not nama:\n            continue\n        email = (b.get("email") or "").strip().lower() or None\n        hasil.append({"name": nama.title(), "email": email, "phone": rapikan_hp(b.get("telepon"))})\n    return hasil\n',
     awal='def baca_pelanggan(teks_csv):\n    pass\n',
     tes=['baca_pelanggan("nama,email,telepon\\n  budi santoso ,Budi@Mail.COM ,0812-3456-7890\\nANI,,021 555\\n,x@y.z,0811111111\\n\\"lia, s.kom\\",lia@a.id,+62 811 2222 3333")',
          'baca_pelanggan("nama,email,telepon\\n")',
          'baca_pelanggan("nama,email,telepon\\nTono,tono@x.id,")'],
     petunjuk=["csv.DictReader(io.StringIO(teks)) memberi dict per baris dan aman untuk nilai berkoma di dalam kutip.", "Buat fungsi kecil rapikan_hp() seperti tantangan normalisasi telepon. Ekspresi teks or None mengubah teks kosong menjadi None."],
     jelas="Membersihkan data sebelum impor jauh lebih murah daripada membersihkan kontak ganda di CRM. Fungsi kecil rapikan_hp bisa diuji terpisah.",
     cek={'baca_pelanggan("nama,email,telepon\\n")': []}),
   dict(judul="Mendeteksi pelanggan kembar", fungsi="kembar_email",
     soal="Buat <code>kembar_email(pelanggan)</code> (hasil bagian A) yang mengembalikan dict <code>{email: [nama, ...]}</code> hanya untuk email yang dipakai lebih dari satu pelanggan. Nama dalam urutan kemunculan. Email None diabaikan. Harus O(n).",
     solusi='def kembar_email(pelanggan):\n    per_email = {}\n    for p in pelanggan:\n        if p["email"]:\n            per_email.setdefault(p["email"], []).append(p["name"])\n    return {e: n for e, n in per_email.items() if len(n) > 1}\n',
     awal='def kembar_email(pelanggan):\n    pass\n',
     tes=['kembar_email(baca_pelanggan("nama,email,telepon\\nBudi,budi@mail.com,\\nBUDI S,Budi@Mail.com ,\\nAni,,\\nTono,,\\nCita,cita@x.id,"))',
          'kembar_email([])',
          'kembar_email([{"name": "A", "email": "a@x", "phone": None}, {"name": "B", "email": "b@x", "phone": None}])'],
     petunjuk=["Kelompokkan dengan dict email → list nama (setdefault).", "Saring kelompok yang panjangnya > 1 dengan dict comprehension."],
     jelas="Pengelompokan dengan dict sekali jalan (O(n)) jauh lebih cepat daripada membandingkan setiap pasangan pelanggan (O(n²)) untuk ribuan kontak.",
     cek={'kembar_email([])': {}}),
   dict(judul="vals untuk res.partner", fungsi="vals_partner",
     soal="Buat <code>vals_partner(teks_csv, tag_id)</code> yang memakai bagian A, lalu mengembalikan list dict vals siap <code>create()</code>: kunci <code>name</code>, <code>email</code> (hanya bila ada), <code>phone</code> (hanya bila ada), dan <code>category_id</code> = <code>[(6, 0, [tag_id])]</code>. Untuk email kembar, hanya pelanggan <b>pertama</b> yang dibuat.",
     solusi='def vals_partner(teks_csv, tag_id):\n    hasil, sudah = [], set()\n    for p in baca_pelanggan(teks_csv):\n        if p["email"]:\n            if p["email"] in sudah:\n                continue\n            sudah.add(p["email"])\n        vals = {"name": p["name"], "category_id": [(6, 0, [tag_id])]}\n        if p["email"]:\n            vals["email"] = p["email"]\n        if p["phone"]:\n            vals["phone"] = p["phone"]\n        hasil.append(vals)\n    return hasil\n',
     awal='def vals_partner(teks_csv, tag_id):\n    pass\n',
     tes=['vals_partner("nama,email,telepon\\nBudi,budi@mail.com,0812-3456-7890\\nBUDI S,Budi@Mail.com,\\nAni,,", 4)',
          'vals_partner("nama,email,telepon\\n", 1)',
          'vals_partner("nama,email,telepon\\nTono,,021", 2)'],
     petunjuk=["Panggil baca_pelanggan, simpan email yang sudah dipakai di set.", "Bangun vals mulai dari name dan category_id, lalu tambahkan email/phone hanya bila ada nilainya."],
     jelas="(6, 0, [ids]) = Command.set(ids): mengisi Many2many category_id (tag pelanggan). Tidak menyertakan kunci kosong mencegah data lama tertimpa False saat write.",
     cek={'vals_partner("nama,email,telepon\\nTono,,021", 2)': [{"name": "Tono", "category_id": [(6, 0, [2])]}]}),
  ])

