ujian("uji-ct-2", "ct", "security", "Modul perpustakaan mini", "Bab 6–10: compute & constraint, ORM, inheritance & action, view, keamanan",
  "Perpustakaan kampus memakai Odoo. Kamu menulis logika model library.loan: status otomatis, tombol pengembalian, dan rekap per anggota. Data memakai recordset tiruan; HARI_INI sudah tersedia.",
  [dict(judul="_compute_status", fungsi="_compute_status",
     soal="Tulis <code>_compute_status(self)</code> untuk peminjaman (<code>date_due</code>, <code>date_return</code> teks ISO atau False, <code>fee_per_day</code>). Isi <code>loan.state</code>: <code>\"returned\"</code> bila sudah kembali, <code>\"late\"</code> bila belum kembali dan <code>HARI_INI</code> &gt; date_due, selain itu <code>\"borrowed\"</code>. Isi juga <code>loan.fine</code> = hari terlambat (terhadap date_return, atau HARI_INI bila belum kembali; minimal 0) × fee_per_day.",
     solusi='from datetime import date\n\n\ndef _hari_telat(loan):\n    akhir = date.fromisoformat(loan.date_return or HARI_INI)\n    return max(0, (akhir - date.fromisoformat(loan.date_due)).days)\n\n\ndef _compute_status(self):\n    for loan in self:\n        if loan.date_return:\n            loan.state = "returned"\n        elif HARI_INI > loan.date_due:\n            loan.state = "late"\n        else:\n            loan.state = "borrowed"\n        loan.fine = _hari_telat(loan) * loan.fee_per_day\n',
     awal='def _compute_status(self):\n    for loan in self:\n        pass\n',
     tes=['a = Record(date_due="2026-11-30", date_return=False, fee_per_day=1000)\nb = Record(date_due="2026-11-20", date_return=False, fee_per_day=1000)\nc = Record(date_due="2026-11-20", date_return="2026-11-22", fee_per_day=1000)\n_compute_status(rs(a, b, c))\nhasil = [(x.state, x.fine) for x in (a, b, c)]',
          'd = Record(date_due="2026-11-24", date_return=False, fee_per_day=500)\n_compute_status(rs(d))\nhasil = (d.state, d.fine)',
          '_compute_status(rs())\nhasil = "ok"'],
     petunjuk=["Urutan if: returned dulu, lalu late, lalu borrowed. Teks ISO bisa dibandingkan dengan >.", "Buat fungsi bantu _hari_telat(loan) yang memakai date_return or HARI_INI."],
     jelas="Jatuh tempo tepat hari ini belum terlambat (tes 2). Pengembalian terlambat tetap kena denda walau statusnya returned.",
     cek={'d = Record(date_due="2026-11-24", date_return=False, fee_per_day=500)\n_compute_status(rs(d))\nhasil = (d.state, d.fine)': ("borrowed", 0)}),
   dict(judul="action_return", fungsi="action_return",
     soal="Tulis <code>action_return(self)</code> (tombol \"Kembalikan\"). Periksa semua record dulu: jika ada yang sudah <code>returned</code>, lempar <code>UserError</code> dan tidak ada yang berubah. Selain itu isi <code>date_return = HARI_INI</code> untuk semua, jalankan <code>_compute_status</code>, dan kembalikan total denda yang harus dibayar (jumlah <code>fine</code>).",
     solusi='def action_return(self):\n    _compute_status(self)\n    if any(loan.state == "returned" for loan in self):\n        raise UserError("Ada buku yang sudah dikembalikan.")\n    for loan in self:\n        loan.date_return = HARI_INI\n    _compute_status(self)\n    return sum(self.mapped("fine"))\n',
     awal='def action_return(self):\n    pass\n',
     tes=['a = Record(date_due="2026-11-20", date_return=False, fee_per_day=1000)\nb = Record(date_due="2026-11-30", date_return=False, fee_per_day=1000)\ntotal = action_return(rs(a, b))\nhasil = (total, a.state, b.state, a.date_return)',
          'a = Record(date_due="2026-11-20", date_return=False, fee_per_day=1000)\nc = Record(date_due="2026-11-20", date_return="2026-11-21", fee_per_day=1000)\ntry:\n    action_return(rs(a, c))\n    hasil = "tidak error"\nexcept UserError:\n    hasil = ("UserError", a.date_return)',
          'hasil = action_return(rs())'],
     petunjuk=["Hitung status dulu (_compute_status), lalu cek dengan any(...) sebelum mengubah apa pun.", "Setelah mengisi date_return, hitung ulang status dan jumlahkan fine dengan mapped(\"fine\")."],
     jelas="Memeriksa semua record sebelum menulis mencegah perubahan setengah jalan. Mengembalikan nilai dari action berguna untuk ditampilkan atau dites.",
     cek={'hasil = action_return(rs())': 0}),
   dict(judul="Rekap per anggota", fungsi="rekap_anggota",
     soal="Tulis <code>rekap_anggota(loans)</code>. Jalankan <code>_compute_status</code>, lalu kembalikan list dict <code>{\"anggota\": nama, \"pinjam\": jumlah, \"terlambat\": jumlah state late, \"denda\": total fine}</code> per <code>member_id.name</code>, diurutkan dari denda terbesar (seri: nama abjad).",
     solusi='def rekap_anggota(loans):\n    _compute_status(loans)\n    rekap = {}\n    for loan in loans:\n        nama = loan.member_id.name\n        r = rekap.setdefault(nama, {"anggota": nama, "pinjam": 0, "terlambat": 0, "denda": 0})\n        r["pinjam"] += 1\n        r["terlambat"] += loan.state == "late"\n        r["denda"] += loan.fine\n    return sorted(rekap.values(), key=lambda r: (-r["denda"], r["anggota"]))\n',
     awal='def rekap_anggota(loans):\n    pass\n',
     tes=['ani, budi = Record(name="Ani"), Record(name="Budi")\nL = rs(Record(member_id=ani, date_due="2026-11-20", date_return=False, fee_per_day=1000), Record(member_id=budi, date_due="2026-11-30", date_return=False, fee_per_day=1000), Record(member_id=ani, date_due="2026-11-10", date_return="2026-11-12", fee_per_day=500), Record(member_id=budi, date_due="2026-11-22", date_return=False, fee_per_day=2000))\nhasil = rekap_anggota(L)',
          'hasil = rekap_anggota(rs())',
          'z, y = Record(name="Zaki"), Record(name="Yani")\nL = rs(Record(member_id=z, date_due="2026-12-01", date_return=False, fee_per_day=1), Record(member_id=y, date_due="2026-12-01", date_return=False, fee_per_day=1))\nhasil = rekap_anggota(L)'],
     petunjuk=["Kelompokkan per loan.member_id.name dengan dict (setdefault), seperti read_group.", "True bernilai 1 saat dijumlahkan: r[\"terlambat\"] += loan.state == \"late\"."],
     jelas="Di Odoo sungguhan rekap ini ditulis dengan _read_group([], ['member_id'], ['__count', 'fine:sum']) agar dihitung database, tetapi logikanya sama.",
     cek={'hasil = rekap_anggota(rs())': []}),
  ], pre=PRE_ODOO + '\nHARI_INI = "2026-11-24"\n')
